create or replace function ascent_game.generate_varied_climb(seed text, player uuid) returns jsonb language plpgsql stable set search_path='' as $fn$
declare theme record; holds text[]; pitches jsonb:='[]'; prior_clues text[]; prior_signatures text[]; used_clues text[]:='{}'; chosen text[]; candidate int; phrase_count int; signature text; best_score int; score int; phase int; perfect int;
begin
 select coalesce(array_agg(distinct clue),'{}') into prior_clues from ascent_game.runs r join ascent_game.circuits c on c.route_id=case when r.scope like 'practice:%' then r.scope else 'daily:'||to_char(r.day,'YYYY-MM-DD') end cross join lateral jsonb_array_elements(c.boards) p cross join lateral jsonb_array_elements_text(p->'clues') clue where r.ticket=player and c.route_id<>seed;
 select coalesce(array_agg(distinct ascent_game.pitch_signature(p)),'{}') into prior_signatures from ascent_game.runs r join ascent_game.circuits c on c.route_id=case when r.scope like 'practice:%' then r.scope else 'daily:'||to_char(r.day,'YYYY-MM-DD') end cross join lateral jsonb_array_elements(c.boards) p where r.ticket=player and c.route_id<>seed;
 for theme in
  with personal as (select p->>'target' target,count(distinct c.route_id) n from ascent_game.runs r join ascent_game.circuits c on c.route_id=case when r.scope like 'practice:%' then r.scope else 'daily:'||to_char(r.day,'YYYY-MM-DD') end cross join lateral jsonb_array_elements(c.boards) p where r.ticket=player and c.route_id<>seed group by 1),
  overall as (select p->>'target' target,count(*) n from ascent_game.circuits c cross join lateral jsonb_array_elements(c.boards) p where c.lex_version=7 group by 1)
  select t.* from ascent_game.theme_catalog_v7 t left join personal u using(target) left join overall g using(target) order by coalesce(u.n,0),coalesce(g.n,0),md5(seed||t.target),t.target
 loop
   chosen:=null;best_score:=2147483647;
   phrase_count:=2+case when jsonb_array_length(pitches)=mod(get_byte(decode(md5(seed),'hex'),1),5) and mod(get_byte(decode(md5(seed),'hex'),0),2)=1 then 1 else 0 end;
   for candidate in 1..72 loop
     holds:=array(select clue from ((select c clue from unnest(theme.clues) c where c not like '% %' and not(c=any(used_clues)) order by (c=any(prior_clues)),md5(seed||theme.target||candidate||c) limit (6-phrase_count)) union all (select c clue from unnest(theme.clues) c where c like '% %' and not(c=any(used_clues)) order by (c=any(prior_clues)),md5(seed||theme.target||candidate||c) limit phrase_count)) pool order by md5(seed||candidate||'pos'||clue));
     if cardinality(holds)<>6 then continue;end if;
     signature:=ascent_game.pitch_signature(jsonb_build_object('clues',holds));
     if signature=any(prior_signatures) or exists(select 1 from ascent_game.published_pitches where published_pitches.signature=ascent_game.pitch_signature(jsonb_build_object('clues',holds))) then continue;end if;
     select count(*) into perfect from (select word from ascent_game.circuit_lexicon l cross join lateral jsonb_object_keys(l.links) word where l.edition=7 and l.clue=any(holds) and word<>all(holds) group by word having count(*)=6) x;
     if perfect<>1 or theme.target=any(holds) then continue;end if;
     select count(*) into score from unnest(holds) clue where clue=any(prior_clues);
     if score<best_score then chosen:=holds;best_score:=score;end if;
     exit when best_score=0;
   end loop;
   if chosen is null then continue;end if;
   pitches:=pitches||jsonb_build_array(jsonb_build_object('target',theme.target,'clues',chosen));
   used_clues:=used_clues||chosen;
   if jsonb_array_length(pitches)=5 then return pitches;end if;
 end loop;
 raise exception 'No fresh climb available';
end;$fn$;
revoke all on function ascent_game.generate_varied_climb(text,uuid) from public,anon,authenticated;
do $patch$
declare def text; updated text;
begin
 select pg_get_functiondef('public.ascent_circuit(uuid,text,date,integer,text,date,uuid)'::regprocedure) into def;
 updated:=replace(def,'pitches:=ascent_game.generate_theme_climb(route_key);dictionary_version:=6;', 'perform pg_advisory_xact_lock(hashtextextended(''ascent-route-generation'',0)); select c.boards,c.lex_version into pitches,dictionary_version from ascent_game.circuits c where c.route_id=route_key; if pitches is null then pitches:=ascent_game.generate_varied_climb(route_key,p_ticket);dictionary_version:=7; end if;');
 if updated=def then raise exception 'Expected circuit generation block missing';end if;
 execute updated;
end;$patch$;

